#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <PubSubClient.h>

// =====================================================
//                     НАСТРОЙКИ
// =====================================================

// Wi-Fi
const char* WIFI_SSID     = "OpenWRT";
const char* WIFI_PASSWORD = "331191481";

// Bambu Lab A1
const char* PRINTER_IP   = "192.168.2.142";
const char* PRINTER_SN   = "03900D622718386";
const char* ACCESS_CODE  = "25465333";

// GPIO, который идёт на MOSFET
const int LED_PIN = 25;

// Для обычного MOSFET-модуля:
const int LED_ON  = HIGH;
const int LED_OFF = LOW;

// =====================================================

WiFiClientSecure secureClient;
PubSubClient mqtt(secureClient);

String reportTopic;
String requestTopic;

bool lightState = false;

unsigned long lastMqttMessage = 0;
unsigned long lastMqttReconnect = 0;
unsigned long lastWiFiReconnect = 0;
unsigned long lastPushAll = 0;

const unsigned long MQTT_RECONNECT_INTERVAL = 5000;
const unsigned long WIFI_RECONNECT_INTERVAL = 5000;
const unsigned long PUSHALL_INTERVAL = 30000;

// Если 3 минуты вообще нет связи с принтером — выключаем свет
const unsigned long PRINTER_TIMEOUT = 180000;


// =====================================================
//                         СВЕТ
// =====================================================

void setLight(bool on) {

  if (lightState == on) {
    return;
  }

  lightState = on;

  digitalWrite(
    LED_PIN,
    on ? LED_ON : LED_OFF
  );

  Serial.println(
    on ? ">>> LIGHT ON" : ">>> LIGHT OFF"
  );
}


// =====================================================
//                СОСТОЯНИЕ ПРИНТЕРА
// =====================================================

void handlePrinterState(String state) {

  state.trim();
  state.toUpperCase();

  Serial.print("Printer state: ");
  Serial.println(state);

  /*
      Свет ВКЛЮЧЕН:

      INIT     - запуск задания
      PREPARE  - подготовка
      SLICING  - подготовка задания
      RUNNING  - печать
      PAUSE    - пауза

      Свет ВЫКЛЮЧЕН:

      IDLE
      FINISH
      FAILED
      OFFLINE
  */

  bool printerBusy =
      state == "INIT" ||
      state == "PREPARE" ||
      state == "SLICING" ||
      state == "RUNNING" ||
      state == "PAUSE";

  setLight(printerBusy);
}


// =====================================================
//          ДОСТАЁМ gcode_state ИЗ JSON
// =====================================================

void parsePrinterMessage(byte* payload, unsigned int length) {

  String message;
  message.reserve(length + 1);

  for (unsigned int i = 0; i < length; i++) {
    message += (char)payload[i];
  }

  int keyPos = message.indexOf("\"gcode_state\"");

  // В Bambu MQTT сообщения частичные.
  // Если gcode_state в этом сообщении нет — ничего не меняем.
  if (keyPos < 0) {
    return;
  }

  int colonPos = message.indexOf(':', keyPos);

  if (colonPos < 0) {
    return;
  }

  int quote1 = message.indexOf('"', colonPos + 1);

  if (quote1 < 0) {
    return;
  }

  int quote2 = message.indexOf('"', quote1 + 1);

  if (quote2 < 0) {
    return;
  }

  String state =
      message.substring(quote1 + 1, quote2);

  handlePrinterState(state);
}


// =====================================================
//                     MQTT CALLBACK
// =====================================================

void mqttCallback(
  char* topic,
  byte* payload,
  unsigned int length
) {

  lastMqttMessage = millis();

  Serial.print("MQTT RX: ");
  Serial.print(topic);

  Serial.print(" | ");
  Serial.print(length);
  Serial.println(" bytes");

  parsePrinterMessage(payload, length);
}


// =====================================================
//             ЗАПРОС ПОЛНОГО СОСТОЯНИЯ
// =====================================================

void requestPrinterStatus() {

  if (!mqtt.connected()) {
    return;
  }

  const char* request =
    "{"
      "\"pushing\":{"
        "\"sequence_id\":\"1\","
        "\"command\":\"pushall\","
        "\"version\":1,"
        "\"push_target\":1"
      "}"
    "}";

  bool result =
      mqtt.publish(
        requestTopic.c_str(),
        request
      );

  Serial.println(
    result ?
    "pushall sent" :
    "pushall ERROR"
  );

  lastPushAll = millis();
}


// =====================================================
//                   ПОДКЛЮЧЕНИЕ MQTT
// =====================================================

bool connectMQTT() {

  Serial.println();
  Serial.println("Connecting to Bambu A1 MQTT...");

  String clientId =
      "ESP32-A1-Light-" +
      String((uint32_t)ESP.getEfuseMac(), HEX);

  bool connected =
      mqtt.connect(
        clientId.c_str(),
        "bblp",
        ACCESS_CODE
      );

  if (!connected) {

    Serial.print("MQTT connection error: ");
    Serial.println(mqtt.state());

    return false;
  }

  Serial.println("MQTT CONNECTED");

  if (mqtt.subscribe(reportTopic.c_str())) {

    Serial.print("Subscribed: ");
    Serial.println(reportTopic);

  } else {

    Serial.println("MQTT subscribe ERROR");
  }

  delay(300);

  requestPrinterStatus();

  return true;
}


// =====================================================
//                       WIFI
// =====================================================

void connectWiFi() {

  Serial.println();
  Serial.print("Connecting to Wi-Fi: ");
  Serial.println(WIFI_SSID);

  WiFi.mode(WIFI_STA);

  WiFi.begin(
    WIFI_SSID,
    WIFI_PASSWORD
  );

  unsigned long start = millis();

  while (
    WiFi.status() != WL_CONNECTED &&
    millis() - start < 20000
  ) {

    delay(500);
    Serial.print(".");
  }

  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {

    Serial.println("Wi-Fi CONNECTED");

    Serial.print("ESP32 IP: ");
    Serial.println(WiFi.localIP());

    Serial.print("Printer IP: ");
    Serial.println(PRINTER_IP);

  } else {

    Serial.println("Wi-Fi connection FAILED");
  }
}


// =====================================================
//                       SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  delay(500);

  Serial.println();
  Serial.println("==============================");
  Serial.println(" Bambu Lab A1 Auto Light");
  Serial.println("==============================");

  pinMode(LED_PIN, OUTPUT);

  digitalWrite(LED_PIN, LED_OFF);
  lightState = false;

  reportTopic =
      "device/" +
      String(PRINTER_SN) +
      "/report";

  requestTopic =
      "device/" +
      String(PRINTER_SN) +
      "/request";

  connectWiFi();

  // Bambu использует TLS с локальным сертификатом.
  secureClient.setInsecure();

  mqtt.setServer(
    PRINTER_IP,
    8883
  );

  mqtt.setCallback(mqttCallback);

  // Полный Bambu status достаточно большой.
  mqtt.setBufferSize(16384);

  mqtt.setKeepAlive(30);

  if (WiFi.status() == WL_CONNECTED) {
    connectMQTT();
  }
}


// =====================================================
//                         LOOP
// =====================================================

void loop() {

  // -------------------------
  // Wi-Fi
  // -------------------------

  if (WiFi.status() != WL_CONNECTED) {

    setLight(false);

    if (
      millis() - lastWiFiReconnect >=
      WIFI_RECONNECT_INTERVAL
    ) {

      lastWiFiReconnect = millis();

      Serial.println("Wi-Fi reconnect...");

      WiFi.disconnect();
      WiFi.begin(
        WIFI_SSID,
        WIFI_PASSWORD
      );
    }

    delay(10);
    return;
  }


  // -------------------------
  // MQTT
  // -------------------------

  if (!mqtt.connected()) {

    setLight(false);

    if (
      millis() - lastMqttReconnect >=
      MQTT_RECONNECT_INTERVAL
    ) {

      lastMqttReconnect = millis();

      connectMQTT();
    }

  } else {

    mqtt.loop();


    // Каждые 30 секунд спрашиваем полный статус
    if (
      millis() - lastPushAll >=
      PUSHALL_INTERVAL
    ) {

      requestPrinterStatus();
    }
  }


  // -------------------------
  // FAILSAFE
  // -------------------------

  if (
    lastMqttMessage != 0 &&
    millis() - lastMqttMessage >
    PRINTER_TIMEOUT
  ) {

    Serial.println(
      "Printer connection timeout"
    );

    setLight(false);

    lastMqttMessage = 0;
  }

  delay(5);
}
